def drag_force(height, velocity, Cd=0.4, A=10.5):
  p = 1.225 * np.exp(-height/8434)
  drag = Cd * A * p * (velocity ** 2) / 2
  return drag

def weight(gravity, mass, angle):
  weight = mass * gravity * np.sin(angle)
  return weight

