def pressure(height, velocity):
  p = 1.225 * np.exp(-height/8434)
  q = p * (velocity ** 2) / 2
  return q

def plot_trajectory(altitude, downrange_distance):
    R_earth = 6378

    # Angle is ratio between downrange distance (circumference) and the radius to be in radians
    angle = np.array(downrange_distance) / R_earth

    # Compute rocket trajectory (x,y)
    x_traj = (R_earth + np.array(altitude)) * np.cos(angle)
    y_traj = (R_earth + np.array(altitude)) * np.sin(angle)

    # Plot Earth as a circle
    theta = np.linspace(0, 2*np.pi, 1000)
    x_earth = R_earth * np.cos(theta)
    y_earth = R_earth * np.sin(theta)
    for c in range(len(telemetry["angle"])):
      if c == 1:
        plt.legend()
      plt.figure(figsize=(6,6))
      plt.plot(x_earth, y_earth, color='black', linestyle = "--", label="Earth")
      plt.plot(x_traj[:c], y_traj[:c], color='blue', label="Rocket trajectory")
      plt.axis("equal")
      plt.xlabel("X (km)")
      plt.ylabel("Y (km)")
      plt.title("Rocket trajectory vs Earth")
      plt.pause(0.01)
    plt.show()
